search.beforeRequest:
// Sent as a form value, with a space as +, as the original sends it.
const form = (text) => encodeURIComponent(text).replace(/[!'()~]/g, (c) => '%' + c.charCodeAt(0).toString(16).toUpperCase()).replace(/%20/g, '+');
request.url += '?q=' + form(inputs.search_text);
const type = JSON.parse(inputs.types).join(',');
if (type !== '') request.query.type = type;
return request;

get_playlists.afterResponse:
if (inputs.all !== 'true') return response;
const items = response.items.slice();
let total = response.total;
while (items.length < total) {
  const page = call({method: 'GET', url: request.url, query: {limit: '50', offset: String(items.length)}});
  total = page.total;
  items.push(...page.items);
}
return {total: items.length, items};

