create_playlist.beforeRequest:
const me = call({method: 'GET', url: '/me'});
request.url += '/' + encodeURIComponent(me.id) + '/playlists';
return request;

playlist_items_changed.afterResponse:
const md5 = (text) => {
  const shifts = [7, 12, 17, 22, 5, 9, 14, 20, 4, 11, 16, 23, 6, 10, 15, 21];
  const bytes = [...unescape(encodeURIComponent(text))].map((character) => character.charCodeAt(0));
  const bits = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  for (let index = 0; index < 8; index++) bytes.push(Math.floor(bits / 2 ** (8 * index)) & 255);
  const state = [0x67452301, 0xefcdab89, 0x98badcfe, 0x10325476];
  for (let offset = 0; offset < bytes.length; offset += 64) {
    const words = [];
    for (let index = 0; index < 16; index++) words.push(bytes[offset + 4 * index] | bytes[offset + 4 * index + 1] << 8 | bytes[offset + 4 * index + 2] << 16 | bytes[offset + 4 * index + 3] << 24);
    let [a, b, c, d] = state;
    for (let round = 0; round < 64; round++) {
      const quarter = round >> 4;
      const mixed = [(b & c) | (~b & d), (d & b) | (~d & c), b ^ c ^ d, c ^ (b | ~d)][quarter];
      const word = words[[round, 5 * round + 1, 3 * round + 5, 7 * round][quarter] % 16];
      const sum = (mixed + a + (Math.floor(Math.abs(Math.sin(round + 1)) * 2 ** 32) | 0) + word) | 0;
      const shift = shifts[quarter * 4 + round % 4];
      [a, d, c] = [d, c, b];
      b = (b + (sum << shift | sum >>> (32 - shift))) | 0;
    }
    [a, b, c, d].forEach((value, index) => { state[index] = (state[index] + value) | 0; });
  }
  return state.map((value) => [0, 8, 16, 24].map((shift) => (value >>> shift & 255).toString(16).padStart(2, '0')).join('')).join('');
};
const items = response.items.slice();
let total = response.total;
while (items.length < total) {
  const page = call({method: 'GET', url: '/playlists/' + encodeURIComponent(inputs.playlist_id) + '/tracks', query: {limit: '50', offset: String(items.length)}});
  total = page.total;
  items.push(...page.items);
}
// A fingerprint of the track order, so that adds, removals and moves are all a change.
const hash = md5(items.map((item) => item.track.id).join(','));
if (memory.playlist_changed_trigger_hash === hash) return [];
memory.playlist_changed_trigger_hash = hash;
return [{total: items.length, items}];
